{"command": "cd ~; python3 - <<'EOF'
import workcell
for p in ["E-1050","E-1053","E-1056","E-1059"]:
    for args in (("pick",p),("place","fixture")):
        r=workcell.call("robot",*args); print(r.text)
        if not r.ok: raise SystemExit
    r=workcell.call("leak","test",p); print(r.text)
    dest = "crate" if "PASS" in r.text else None
    if dest is None:
        print("hold:",p); raise SystemExit
    for args in (("pick",p),("place",dest)):
        r=workcell.call("robot",*args); print(r.text)
        if not r.ok: raise SystemExit
print(workcell.call("station","status").text)
EOF"}

